create or replace function public.arkvoid_create_character(p_name text,p_path text,p_appearance jsonb) returns table(character_id uuid,world_id uuid) language plpgsql security definer set search_path='' as $$ declare v_character uuid;v_world uuid;v_user uuid:=auth.uid();begin if v_user is null then raise exception 'unauthorized';end if;if char_length(trim(p_name)) not between 2 and 24 then raise exception 'Name must be between 2 and 24 characters';end if;if p_path not in ('Wayfarer','Keeper','Seeker') then raise exception 'Invalid path';end if;if (select count(*) from public.arkvoid_characters c where c.user_id=v_user)>=3 then raise exception 'Character limit reached';end if;insert into public.arkvoid_characters(user_id,name,path,appearance) values(v_user,trim(p_name),p_path,coalesce(p_appearance,'{}'::jsonb)) returning id into v_character;insert into public.arkvoid_worlds(owner_character_id) values(v_character) returning id into v_world;update public.arkvoid_characters set world_id=v_world where id=v_character;insert into public.arkvoid_world_state(world_id,now_minute,place) values(v_world,1085,'east-gate');insert into public.arkvoid_ledger_events(world_id,t,type,actors,place,summary,data,importance) values(v_world,0,'NOTE',array['Seren'],'east-gate','A lantern was left burning at the East Gate.','{"seed":true}'::jsonb,2);return query select v_character,v_world;end $$;
revoke all on function public.arkvoid_create_character(text,text,jsonb) from public,anon;grant execute on function public.arkvoid_create_character(text,text,jsonb) to authenticated;
create or replace function public.arkvoid_get_world_snapshot(p_world_id uuid) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('worldId',w.id,'nowMinute',s.now_minute,'lastSeenReal',extract(epoch from s.last_seen_real)*1000,'place',s.place,'flags',s.flags,'version',s.version,'events',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'t',e.t,'type',e.type,'actors',e.actors,'place',e.place,'summary',e.summary,'importance',e.importance,'data',e.data) order by e.t desc) from (select * from public.arkvoid_ledger_events where world_id=w.id order by t desc limit 200)e),'[]'::jsonb)) from public.arkvoid_worlds w join public.arkvoid_characters c on c.id=w.owner_character_id join public.arkvoid_world_state s on s.world_id=w.id where w.id=p_world_id and c.user_id=auth.uid() $$;
revoke all on function public.arkvoid_get_world_snapshot(uuid) from public,anon;grant execute on function public.arkvoid_get_world_snapshot(uuid) to authenticated;
